<?php
 function isUndefinedProperty ($object, $property, $default = null) { return (isset($object->$property) || (is_object($object) && property_exists($object, $property))) ? $object->$property : $default; } function isNullProperty ($object, $property, $default = null) { return isset($object->$property) ? $object->$property : $default; } function isEmptyProperty ($object, $property, $default = null) { return empty($object->$property) ? $default : $object->$property; } function propertyExistsSQL ($object, $property) { return property_exists($object, $property) ?: 0; } function mergeObjects ($a, $b) { foreach($b as $k => $v) { $a->{$k} = $v; } return $a; } function json_clean_decode($json, $assoc = false, $depth = 512, $options = 0) { if (mb_detect_encoding($json, 'UTF-8', true) === false) { $json = mb_convert_encoding($json, 'UTF-8', 'CP1251'); } else if (substr($json, 0, 3) === (chr(0xEF).chr(0xBB).chr(0xBF))) { $json = substr($json, 3); } $json = preg_replace('#/\*[^*]*\*+([^/][^*]*\*+)*/#', '', $json ?? ''); $json = preg_replace('#([\s\t]//.*)|(^//.*)#', '', $json ?? ''); $json = preg_replace("/(^[\r\n]*|[\r\n]+)[\s\t]*[\r\n]+/", "\n", $json ?? ''); $json = safe_json_decode($json, $assoc, $depth, $options); checkJsonDecode(); return $json; } function checkJsonDecode () { switch (json_last_error()) { case JSON_ERROR_NONE: break; case JSON_ERROR_DEPTH: throw new ErrorException('Ошибка safe_json_decode() - Достигнута максимальная глубина стека'); case JSON_ERROR_STATE_MISMATCH: throw new ErrorException('Ошибка safe_json_decode() - Некорректные разряды или не совпадение режимов'); case JSON_ERROR_CTRL_CHAR: throw new ErrorException('Ошибка safe_json_decode() - Некорректный управляющий символ'); case JSON_ERROR_SYNTAX: throw new ErrorException('Ошибка safe_json_decode() - Синтаксическая ошибка, некорректный JSON'); case JSON_ERROR_UTF8: throw new ErrorException('Ошибка safe_json_decode() - Некорректные символы UTF-8, возможно неверная кодировка'); default: throw new ErrorException('Ошибка safe_json_decode - Неизвестная ошибка'); } } function getObjValueByPath ($obj, $path, $defaultValue = null) { if (!$obj || !is_object($obj) || !$path) { return $defaultValue; } for ($i = 0, $path = safe_explode('/', $path), $len = count($path); $i < $len; $i++) { if (!property_exists($obj, $path[$i])) { return $defaultValue; } $obj = $obj->{$path[$i]}; } return $obj; } function setObjValueByPath ($obj, $path, $value, $create = false) { if (!$obj || !is_object($obj) || !$path) { return; } for ($i = 0, $path = safe_explode('/', $path), $len = count($path); $i < $len - 1; $i++) { if (!property_exists($obj, $path[$i])) { if ($create) { $obj->{$path[$i]} = new stdClass(); } else { return; } } $obj = $obj->{$path[$i]}; } if (is_object($obj)) { $obj->{$path[$len - 1]} = $value; } }